// A simple, executable Rust implementation matching the spec intent.
// We treat sequences as Vec<char> and preserve relative order in the filter.

/// Returns true iff `s` starts with prefix `p`:
/// - always true if `p` is empty
/// - otherwise `s.len() >= p.len()` and all corresponding chars match
///
/// (This is the executable counterpart of the `spec fn starts_with`.)
pub fn starts_with(s: &[char], p: &[char]) -> bool {
    if p.is_empty() {
        return true;
    }
    if s.len() < p.len() {
        return false;
    }
    // Compare elementwise up to prefix length
    s.iter().zip(p.iter()).all(|(a, b)| a == b)
}

/// Matches the requested helper signature.
pub fn has_prefix(v: &Vec<char>, p: &Vec<char>) -> bool {
    starts_with(v.as_slice(), p.as_slice())
}

/// Filters `xs`, keeping exactly the sequences that start with prefix `p`,
/// preserving their relative order.
pub fn filter_by_prefix(xs: Vec<Vec<char>>, p: Vec<char>) -> Vec<Vec<char>> {
    xs.into_iter()
        .filter(|s| starts_with(s.as_slice(), p.as_slice()))
        .collect()
}

